.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-search-results{display:grid;gap:10px;margin:0}
.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-search-results>header,.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-nav-group>header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0}
.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-search-results>header h2,.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-nav-group>header h2{margin:0;font-size:13px;font-weight:920;letter-spacing:.065em;text-transform:uppercase;color:var(--dp-text_muted)}
.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-search-results>header span,.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-nav-group>header span{display:inline-flex;align-items:center;min-height:28px;border:1px solid var(--dp-border_soft);border-radius:999px;background:var(--dp-surface_muted);color:var(--dp-text_muted);padding:4px 10px;font-size:11px;font-weight:900}
