.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-search-result:hover{transform:translateY(-1px);border-color:color-mix(in srgb,var(--dp-primary-600,#2563eb) 34%,var(--dp-border));box-shadow:0 16px 36px rgba(15,23,42,.09)}
.dp-panel[data-dp-panel-kind="dashboard"] .dp-panel-search-result span{font-size:10px;font-weight:920;letter-spacing:.075em;text-transform:uppercase;color:var(--dp-text_muted)}
