.dp-panel-main-region>header{position:relative;z-index:7;margin:0;padding:18px 20px;border:1px solid color-mix(in srgb,var(--dp-border) 82%,transparent);border-radius:20px;background:color-mix(in srgb,var(--dp-surface) 92%,transparent);box-shadow:var(--dp-present-shadow-soft);backdrop-filter:blur(18px)}
